//! The application's own chrome icons.
//!
//! This used to be generated by `iced_fontello` from `fonts/fonts.toml`, which
//! pulled a second icon font into the binary purely for the builder's toolbar
//! and tree disclosure arrows. Everything here now names a Lucide icon out of
//! [`crate::icon_lucide`] instead, so there is one icon pipeline rather than
//! two, and the chrome is drawn from the same set the pickers offer.
//!
//! [`crate::icon_lucide`] is built with `build_index`, which carries every
//! family but emits no per-icon functions — an eighty-thousand-function module
//! helps nobody. So these are written by hand: each one resolves its icon by
//! upstream name, once, and renders it.

use std::sync::LazyLock;

use iced::widget::{Text, text};

use crate::icon_lucide::{self, Icon};

/// Every icon font the application needs, ready to register.
pub const FONTS: &[&[u8]] = icon_lucide::FONTS;

/// The family the chrome is drawn from.
const CHROME_FAMILY: &str = "lucide";

/// Names an application icon after its Lucide icon.
///
/// The lookup walks the whole index, so it happens once per icon rather than
/// once per frame.
macro_rules! chrome_icons {
    ($($(#[$meta:meta])* $name:ident => $upstream:literal),* $(,)?) => {
        $(
            $(#[$meta])*
            pub fn $name<'a>() -> Text<'a> {
                static ICON: LazyLock<Icon> = LazyLock::new(|| resolve($upstream));

                icon_lucide::render(*ICON)
            }
        )*

        /// The upstream name behind every icon above.
        #[cfg(test)]
        const CHROME_ICON_NAMES: &[&str] = &[$($upstream),*];
    };
}

chrome_icons! {
    /// Swap two things over.
    arrow_right_left => "arrow-right-left",
    /// The widget palette.
    blocks => "blocks",
    /// A tree row that is open.
    chevron_down => "chevron-down",
    /// A tree row that is closed.
    chevron_right => "chevron-right",
    /// The generated-code view.
    code => "code",
    /// Copy to clipboard.
    copy => "copy",
    /// New project.
    file_plus => "file-plus",
    /// Open a project.
    folder_open => "folder-open",
    /// Home — the main view.
    house => "house",
    /// An explanatory tooltip.
    info => "info",
    /// The theme and style editor.
    palette => "palette",
    /// Edit in place.
    pencil => "pencil",
    /// Add.
    plus => "plus",
    /// Save the project.
    save => "save",
    /// Save the project under a new name.
    save_all => "save-all",
    /// Settings.
    settings => "settings",
    /// Delete.
    trash_2 => "trash-2",
    /// The action editor.
    workflow => "workflow",
}

/// Looks an icon up by upstream name, within one family.
///
/// Family matters: with every set enabled, `arrow-left-right` is both a Lucide
/// icon and a Bootstrap one, and [`icon_lucide::find`] returns whichever comes
/// first in the index.
pub fn find_in(family: &str, name: &str) -> Option<Icon> {
    icon_lucide::ALL_ICONS
        .iter()
        .find(|icon| icon.family == family && icon.name == name)
        .copied()
}

/// Resolves a chrome icon.
///
/// A miss means an upstream rename since this module was written, which
/// `chrome_icons_all_resolve` catches. Rather than panic in the middle of a
/// view, fall back to something visible so the rest of the window still draws.
fn resolve(name: &str) -> Icon {
    const MISSING: Icon = Icon {
        name: "<missing>",
        codepoint: "\u{FFFD}",
        font: iced::Font::DEFAULT,
        family: "",
    };

    find_in(CHROME_FAMILY, name)
        .or_else(|| find_in(CHROME_FAMILY, "circle-help"))
        .unwrap_or(MISSING)
}

/// The `u32` a project stores alongside an icon's name.
pub fn codepoint_of(icon: Icon) -> u32 {
    icon.codepoint.chars().next().map_or(0xFFFD, u32::from)
}

/// Every icon in one family, in the order the index lists them.
pub fn in_family(family: &str) -> impl Iterator<Item = &'static Icon> + Clone {
    icon_lucide::ALL_ICONS
        .iter()
        .filter(move |icon| icon.family == family)
}

/// Moves an icon selection to another family.
///
/// Keeps the icon when the new family draws one by the same name — `settings`
/// turns up in most sets — and otherwise lands on that family's first icon, so
/// a selection never names something its family does not have.
pub fn retarget(family: &str, name: &str) -> (String, u32) {
    match find_in(family, name).or_else(|| in_family(family).next().copied()) {
        Some(icon) => (icon.name.to_string(), codepoint_of(icon)),
        None => (name.to_string(), 0xFFFD),
    }
}

/// Draws an icon picked at runtime, by family and upstream name.
///
/// Unlike the functions above this takes whatever a project stored, so a miss
/// is ordinary rather than a bug — an icon from a family the project no longer
/// enables, say. Those draw as nothing rather than as a tofu box.
pub fn by_name<'a>(family: &str, name: &str) -> Text<'a> {
    match find_in(family, name) {
        Some(icon) => icon_lucide::render(icon),
        None => text(""),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn chrome_icons_all_resolve() {
        for name in CHROME_ICON_NAMES {
            assert!(
                find_in(CHROME_FAMILY, name).is_some(),
                "chrome icon {name:?} is not in the generated index — \
                 it was probably renamed upstream",
            );
        }
    }
}
